例の出力:{"fields":[{"field":1,"units":[{"node_kind":"IMMEDIATE_RESULT_OR_AFTERMATH","parent_quote":null,"qualifiers":[],"quote":"安心した","scope_role":null},{"node_kind":null,"parent_quote":"安心した","qualifiers":[{"kind":"RELATIVE_TIME","quote":"今日"},{"kind":"REASON_MARKER","quote":"ので"}],"quote":"今日は読めたので","scope_role":"WRITTEN_REASON"},{"node_kind":null,"parent_quote":"今日は読めたので","qualifiers":[{"kind":"RELATIVE_TIME","quote":"昨日"},{"kind":"NEGATION","quote":"なかった"}],"quote":"昨日は読めなかった本","scope_role":"ATTRIBUTIVE_CONTENT"}]}]}
